const чистить = s => String(s == null ? '' : s).toLowerCase().replace(/ё/g, 'е').replace(/[«»"()]/g, ' ').replace(/\./g, ' ')
  .split(/\s+/).filter(w => w && !СТОП.has(w)).join(' ').trim();
