  const точно = с.startsWith('=');
  СИНОНИМЫ.push({р, с: чистить(с.replace(/^=/, '')) || с.replace(/^=/, ''), точно});
}
СИНОНИМЫ.sort((a, b) => b.с.length - a.с.length);
function узнать(v){
  if(typeof v === 'number' && Number.isInteger(v) && ПО_КОДУ.has(v)) return ПО_КОДУ.get(v);
  const сыро = String(v == null ? '' : v).trim();
  if(/^\d{1,2}$/.test(сыро) && ПО_КОДУ.has(+сыро)) return ПО_КОДУ.get(+сыро);
  const н = чистить(сыро);
  if(!н) return null;
  /* «Алтай» без «края» — республика, «Алтайский край» — край */
  if(/(^| )алтайск/.test(н)) return ПО_КОДУ.get(22);
