    if(н.startsWith(x.с) || (x.с.indexOf(' ') < 0 && слова.some(w => w.startsWith(x.с)))) return x.р;
  }
  return null;
}

/* --- данные из области: регион и число --- */
async function прочестьДанные(имяЛиста, область){
  const строки = await лист(имяЛиста).прочитать(область);
  const значения = new Map(), не = [], повторы = [];
  for(const ряд of строки){
    const [рег, v] = [ряд[0], ряд[ряд.length > 1 ? 1 : 0]];
    if(рег === null || рег === undefined || рег === '') continue;
    const число = typeof v === 'number' ? v : parseFloat(String(v == null ? '' : v).replace(/\s/g, '').replace(',', '.'));
    const р = узнать(рег);
    if(!р){ if(!(typeof рег === 'string' && /регион|субъект|область|название|наименование/i.test(рег) && !Number.isFinite(число))) не.push(String(рег)); continue; }
    if(!Number.isFinite(число)) continue;
    if(значения.has(р[0])) повторы.push(р[2]);
    значения.set(р[0], (значения.get(р[0]) || 0) + число);
  }
  return {значения, не, повторы};
}
/* --- шкала --- */
function границы(числа, классов, вид){
  const s = числа.slice().sort((a, b) => a - b);
