/* --- рисунок --- */
function нарисовать(значения, н){
  const поОкругам = String(н.показ || '').includes('округ');
  const цвет = {}, показ = {};
  let числа;
  if(поОкругам){
    const суммы = {};
    for(const р of РЕГИОНЫ) if(значения.has(р[0])) суммы[р[4]] = (суммы[р[4]] || 0) + значения.get(р[0]);
    числа = Object.values(суммы);
    for(const р of РЕГИОНЫ) if(суммы[р[4]] !== undefined) показ[р[0]] = суммы[р[4]];
  } else { числа = [...значения.values()]; for(const [к, v] of значения) показ[к] = v; }
  const классов = Math.max(2, Math.min(7, Math.round(+н.классов || 5)));
  const палитра0 = ПАЛИТРЫ[н.палитра] || ПАЛИТРЫ['синяя'];
  /* из семи оттенков берём классов штук, равномерно */
  const палитра = Array.from({length: классов}, (_, i) => палитра0[Math.round(i * (палитра0.length - 1) / (классов - 1))]);
  const гр = границы(числа, классов, н.шкала);
  const П = 46, З = 4, Ш = 17 * (П + З) + З, ВЕРХ = н.заголовок ? 40 : 12, ЛЕГ = 70, В = ВЕРХ + 11 * (П + З) + ЛЕГ;
  let svg = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ' + Ш + ' ' + В + '" font-family="Arial, sans-serif">'
    + '<rect width="' + Ш + '" height="' + В + '" fill="#ffffff"/>';
  if(н.заголовок) svg += '<text x="' + З + '" y="26" font-size="18" font-weight="bold" fill="#151c2e">' + эк(н.заголовок) + '</text>';
  for(const р of РЕГИОНЫ){
    const [к, к3, имя, , фо, c, r] = р;
    const x = З + c * (П + З), y = ВЕРХ + r * (П + З), v = показ[к];
    const заливка = v === undefined ? НЕТ : палитра[Math.min(палитра.length - 1, класс(v, гр))];
    const текст = v === undefined ? '#9aa4b5' : светлый(заливка) ? '#151c2e' : '#ffffff';
    svg += '<g><title>' + эк(имя + (v === undefined ? ' — нет данных' : ': ' + v.toLocaleString('ru-RU')) + (поОкругам ? ' (' + фо + ')' : '')) + '</title>'
      + '<rect x="' + x + '" y="' + y + '" width="' + П + '" height="' + П + '" rx="6" fill="' + заливка + '"' + (v === undefined ? ' stroke="#b8c0cc" stroke-dasharray="3 2"' : '') + '/>'
      + '<text x="' + (x + П / 2) + '" y="' + (y + (н.подписи !== false && v !== undefined ? 20 : 28)) + '" font-size="12" font-weight="bold" text-anchor="middle" fill="' + текст + '">' + к3 + '</text>'
      + (н.подписи !== false && v !== undefined ? '<text x="' + (x + П / 2) + '" y="' + (y + 35) + '" font-size="9" text-anchor="middle" fill="' + текст + '">' + эк(кратко(v)) + '</text>' : '')
      + '</g>';
  }
  /* легенда */
  const ly = ВЕРХ + 11 * (П + З) + 14;
  const ряды = [];
  const мин = Math.min(...числа), макс = Math.max(...числа);
  for(let i = 0; i < палитра.length; i++){
    const от = i === 0 ? мин : гр[i - 1], до = i < гр.length ? гр[i] : макс;
    if(i > гр.length) break;
    ряды.push([палитра[i], кратко(от) + ' – ' + кратко(до)]);
  }
  ряды.push([НЕТ, 'нет данных']);
  let lx = З;
  for(const [ц, т] of ряды){
    svg += '<rect x="' + lx + '" y="' + ly + '" width="18" height="18" rx="3" fill="' + ц + '"' + (ц === НЕТ ? ' stroke="#b8c0cc" stroke-dasharray="3 2"' : '') + '/><text x="' + (lx + 24) + '" y="' + (ly + 13) + '" font-size="12" fill="#151c2e">' + эк(т) + '</text>';
    lx += 30 + т.length * 6.6;
  }
  svg += '<text x="' + З + '" y="' + (ly + 44) + '" font-size="10" fill="#7a8599">Схема субъектов РФ' + (поОкругам ? ', цвет — сумма по федеральному округу' : '') + '. '
    + (н.шкала === 'равные интервалы' ? 'Равные интервалы.' : 'Квантили: в каждом цвете примерно поровну субъектов.') + '</text>';
  return {svg: svg + '</svg>', ширина: Ш, высота: В};
}
function настройки(п){ return {заголовок: п.заголовок || '', шкала: п.шкала || 'квантили', палитра: п.палитра || 'синяя', классов: +п.классов || 5, показ: п.показ || 'субъекты', подписи: п.подписи !== false}; }
function отчёт(д){
  const ряды = [['Узнано субъектов', String(д.значения.size) + ' из 89']];
  if(д.не.length) ряды.push(['Не узнано', д.не.slice(0, 12).join('; ') + (д.не.length > 12 ? '…' : '')]);
  if(д.повторы.length) ряды.push(['Повторы (сложены)', [...new Set(д.повторы)].slice(0, 6).join('; ')]);
  const нет = РЕГИОНЫ.filter(р => !д.значения.has(р[0])).map(р => р[1]);
  if(нет.length && нет.length < 89) ряды.push(['Без данных', нет.slice(0, 20).join(' ') + (нет.length > 20 ? '…' : '')]);
  панель.список('отчёт', ряды);
}

